/**
 * Eligibility Evaluator Engine
 * Evaluates a citizen's profile against structured condition trees generated by the parser.
 * Supports recursive logical groupings (AND / OR) and operators (==, !=, <, <=, >, >=, IN, BETWEEN).
 */

/**
 * Compares an individual citizen attribute with a single atomic condition.
 */
function evaluateCondition(citizenProfile, condition) {
  const { concept, operator, value } = condition;
  const citizenValue = citizenProfile[concept];

  // If citizen profile doesn't have the attribute, condition cannot be satisfied
  if (citizenValue === undefined || citizenValue === null) {
    return {
      passed: false,
      reason: `Citizen profile missing required attribute: ${concept}`,
      condition
    };
  }

  let passed = false;

  switch (operator) {
    case '==':
      if (concept === 'domicile_state' && (value === 'ALL_INDIA' || citizenValue === 'ALL_INDIA')) {
        passed = true;
      } else {
        passed = citizenValue === value;
      }
      break;

    case '!=':
      passed = citizenValue !== value;
      break;

    case '<=':
      passed = Number(citizenValue) <= Number(value);
      break;

    case '<':
      passed = Number(citizenValue) < Number(value);
      break;

    case '>=':
      passed = Number(citizenValue) >= Number(value);
      break;

    case '>':
      passed = Number(citizenValue) > Number(value);
      break;

    case 'IN':
      if (Array.isArray(value)) {
        passed = value.map(v => String(v).toUpperCase()).includes(String(citizenValue).toUpperCase());
      } else {
        passed = String(value).toUpperCase() === String(citizenValue).toUpperCase();
      }
      break;

    case 'NOT_IN':
      if (Array.isArray(value)) {
        passed = !value.map(v => String(v).toUpperCase()).includes(String(citizenValue).toUpperCase());
      } else {
        passed = String(value).toUpperCase() !== String(citizenValue).toUpperCase();
      }
      break;

    case 'BETWEEN':
      if (Array.isArray(value) && value.length === 2) {
        const numVal = Number(citizenValue);
        passed = numVal >= Number(value[0]) && numVal <= Number(value[1]);
      }
      break;

    default:
      passed = false;
  }

  return {
    passed,
    concept,
    operator,
    requiredValue: value,
    citizenValue,
    condition
  };
}

/**
 * Evaluates a structured condition group (AND / OR) recursively against a citizen profile.
 * @param {Object} citizenProfile - Key-value pair of citizen attributes.
 * @param {Object} conditionTree - Root condition group containing logicalOperator and conditions array.
 * @returns {Object} { isEligible, evaluationDetails, failedConditions, matchedConditions }
 */
function evaluateEligibility(citizenProfile, conditionTree) {
  if (!conditionTree || !Array.isArray(conditionTree.conditions) || conditionTree.conditions.length === 0) {
    return {
      isEligible: false,
      reason: 'No structured eligibility conditions available.',
      evaluationDetails: []
    };
  }

  const logicalOp = conditionTree.logicalOperator || 'AND';
  const evaluationDetails = [];
  const matchedConditions = [];
  const failedConditions = [];

  for (const item of conditionTree.conditions) {
    if (item.conditions && Array.isArray(item.conditions)) {
      // Recursive nested group (e.g. nested OR group)
      const subResult = evaluateEligibility(citizenProfile, item);
      evaluationDetails.push(subResult);
      if (subResult.isEligible) {
        matchedConditions.push(item);
      } else {
        failedConditions.push(item);
      }
    } else {
      // Atomic condition
      const check = evaluateCondition(citizenProfile, item);
      evaluationDetails.push(check);
      if (check.passed) {
        matchedConditions.push(check);
      } else {
        failedConditions.push(check);
      }
    }
  }

  let isEligible = false;
  if (logicalOp === 'AND') {
    isEligible = failedConditions.length === 0;
  } else if (logicalOp === 'OR') {
    isEligible = matchedConditions.length > 0;
  }

  return {
    isEligible,
    logicalOperator: logicalOp,
    matchedCount: matchedConditions.length,
    failedCount: failedConditions.length,
    matchedConditions,
    failedConditions,
    evaluationDetails
  };
}

module.exports = {
  evaluateCondition,
  evaluateEligibility
};
